{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C16"],
      "claim": "The closest indolocarbazole analogue LCS1269 is predicted to have human intestinal absorption consistent with bioavailability greater than 30%, supporting high F for the query's indolocarbazole scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Roquinimex showed complete oral bioavailability in healthy volunteers, supporting high F for an amide-containing heteroaromatic drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Becatecarin, another indolocarbazole glycoside, is predicted to have HIA greater than 30%, supporting high F for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Tropisetron had an absolute oral bioavailability of 52% at a 20 mg oral dose in healthy volunteers, supporting high F for a related heteroaromatic drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C41"],
      "claim": "Laquinimod has high oral bioavailability with predictable pharmacokinetics in humans, supporting high F for an amide-containing aromatic drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Nintedanib had an absolute oral bioavailability of only about 5% in healthy volunteers, providing contradictory low-F evidence, but its esterase-mediated first-pass liability is not clearly shared by the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C27"],
      "claim": "Vinpocetine had oral bioavailability as low as 7% in humans due to poor solubility and extensive first-pass metabolism, providing contradictory low-F evidence from a structurally distant scaffold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a staurosporine-like indolocarbazole glycoside with an N-methylbenzamide-substituted sugar. The most structurally relevant evidence, from indolocarbazole glycosides, supports HIA >30%, and multiple experimental oral bioavailability values for related amide/heteroaromatic drugs are ≥20%. The low-F examples are structurally more distant and their specific absorption/first-pass liabilities are not clearly shared. Overall, F ≥20% is better supported.",
  "evidence_gaps": [
    "No direct human absolute oral bioavailability measurement exists for the query or a close staurosporine analogue.",
    "The closest indolocarbazole evidence is based on predicted HIA rather than measured absolute F.",
    "Potential P-glycoprotein efflux and CYP3A4 first-pass metabolism for the query are not experimentally quantified.",
    "Oral bioavailability can be formulation-dependent, and no formulation-specific data are available for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

